import{_ as s,o as n,a as e,b as l}from"./app.BGziXukh.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"缓存控制","link":"/api/SIMD-API/tensor_api/cache_control/cache_control"},{"text":"set_scalar_cache_mode","link":"/api/SIMD-API/tensor_api/cache_control/set_scalar_cache_mode"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/cache_control/set_scalar_cache_mode.md","filePath":"api/SIMD-API/tensor_api/cache_control/set_scalar_cache_mode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"枚举值说明","slug":"枚举值说明","link":"#枚举值说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1794877794000}'),c={name:"api/SIMD-API/tensor_api/cache_control/set_scalar_cache_mode.md"};function t(p,a,d,o,h,i){return n(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>set_scalar_cache_mode</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>配置标量单元访问Global Memory时的L2 Cache管理策略：</p><ul><li>传入<code>load_l2_cache_mode</code>时，设置标量读（load）策略。</li><li>传入<code>store_l2_cache_mode</code>时，设置标量写（store）策略。</li></ul><p>设置后，后续标量路径上的Global Memory读写将按该策略访问L2 Cache，直至再次调用本接口修改。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_scalar_cache_mode</span><span class="p">(</span><span class="n">load_l2_cache_mode</span><span class="w"> </span><span class="n">mode</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_scalar_cache_mode</span><span class="p">(</span><span class="n">store_l2_cache_mode</span><span class="w"> </span><span class="n">mode</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mode</td><td>输入</td><td>L2 Cache管理策略。<code>load_l2_cache_mode</code>作用于标量load路径，<code>store_l2_cache_mode</code>作用于标量store路径。</td></tr></tbody></table><h3 id="枚举值说明">枚举值说明<a class="header-anchor" href="#枚举值说明">​</a></h3><p><code>load_l2_cache_mode</code>的枚举值说明如下：</p><p><strong>表2</strong> <code>load_l2_cache_mode</code>枚举值说明</p><table><thead><tr><th>枚举值</th><th>L2 Cache管理策略</th></tr></thead><tbody><tr><td>normal_first_victim</td><td>启用L2 Cache，并将分配的Cache Line标记为高替换优先级，即在发生替换时优先被淘汰。</td></tr><tr><td>normal_last_victim</td><td>启用L2 Cache，并将分配的Cache Line标记为低替换优先级，即在发生替换时优先保留。</td></tr><tr><td>normal_persistent</td><td>启用L2 Cache。已存入L2 Cache中的数据可能被替换，若需确保特定数据始终保留在L2 Cache中，可采用驻留模式。被标记为驻留模式的Cache Line只能被其他同样被标记为驻留模式的Cache Line替换。</td></tr><tr><td>notalloc_keep</td><td>不启用L2 Cache，每次都直接从GM中读取，并且保持已有Cache Line的状态不变。</td></tr><tr><td>notalloc_clean</td><td>不启用L2 Cache，若L2 Cache中已有同地址缓存会被保留并标记为Clean，标记为Clean的Cache Line被移出L2 Cache时会被直接丢弃。</td></tr><tr><td>notalloc_drop</td><td>不启用L2 Cache，若L2 Cache中已有同地址缓存，会被直接丢弃。</td></tr></tbody></table><p><code>store_l2_cache_mode</code>的枚举值说明如下：</p><p><strong>表3</strong> <code>store_l2_cache_mode</code>枚举值说明</p><table><thead><tr><th>枚举值</th><th>L2 Cache管理策略</th></tr></thead><tbody><tr><td>normal_first_victim</td><td>启用L2 Cache，并将分配的Cache Line标记为高替换优先级，即在发生替换时优先被淘汰。</td></tr><tr><td>normal_last_victim</td><td>启用L2 Cache，并将分配的Cache Line标记为低替换优先级，即在发生替换时优先保留。</td></tr><tr><td>normal_persistent</td><td>启用L2 Cache。已存入L2 Cache中的数据可能被替换，若需确保特定数据始终保留在L2 Cache中，可采用驻留模式。被标记为驻留模式的Cache Line只能被其他同样被标记为驻留模式的Cache Line替换。</td></tr><tr><td>notalloc_clean</td><td>不启用L2 Cache，若L2 Cache中已有同地址缓存会被保留并标记为Clean，标记为Clean的Cache Line被移出L2 Cache时会被直接丢弃。</td></tr></tbody></table><p>Clean和Dirty用于表示Cache Line是否需要回写GM：Clean表示该Cache Line未被标记为需要回写，被替换时可直接丢弃；Dirty表示该Cache Line包含尚未回写GM的修改数据，被替换时需要先将修改数据回写GM。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口的两个函数原型分别作用于标量load与标量store路径。标量load路径影响<a href="../scalar_compute/load_dev.html">load_dev</a>、<a href="datacache_preload.html">datacache_preload</a>和<a href="icache_preload.html">icache_preload</a>；标量store路径影响<a href="../scalar_compute/store_dev.html">store_dev</a>和标量原子操作。</li><li>本接口仅作用于标量访存路径的L2 Cache默认策略，不会改变向量搬运类接口参数中的缓存策略。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例临时将标量load路径设置为<code>normal_first_victim</code>，读取数据后恢复原策略。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>

<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_cache_mode_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">data</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">load_l2_cache_mode</span><span class="w"> </span><span class="n">old_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">get_scalar_load_cache_mode</span><span class="p">();</span>
<span class="w">    </span><span class="n">set_scalar_cache_mode</span><span class="p">(</span><span class="n">load_l2_cache_mode</span><span class="o">::</span><span class="n">normal_first_victim</span><span class="p">);</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">load_dev</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">data</span><span class="p">);</span>
<span class="w">    </span><span class="n">set_scalar_cache_mode</span><span class="p">(</span><span class="n">old_mode</span><span class="p">);</span>
<span class="w">    </span><span class="n">store_dev</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">data</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const v=s(c,[["render",t]]);export{_ as __pageData,v as default};
